values (
  'v3.0-636ee53e1b8d',
  '3.0',
  '8 conjuntos por sexo e estado civil, 160 situacoes, 800 alternativas',
  '{"linguagens":{"PA":"Palavras de Afirmação","QT":"Qualidade de Tempo","RP":"Receber Presentes","FS":"Formas de Servir","TF":"Toque Físico"},"segmentos":{"mulher-solteira":{"titulo":"Mulher · Solteira","cenarios":[{"n":1,"titulo":"Uma semana muito cansativa","situacao":"Você passou por uma semana exaustiva, acumulou responsabilidades e chegou ao fim do dia emocionalmente esgotada. Uma pessoa muito próxima percebe que você não está bem.","pergunta":"Qual atitude faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ela assume espontaneamente uma tarefa que estava pesando sobre você, permitindo que você descanse."},{"letra":"B","codigo":"PA","texto":"Ela reconhece sinceramente tudo o que você enfrentou e diz que admira sua força e seu esforço."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima, abraça você demoradamente e transmite acolhimento por meio do carinho físico."},{"letra":"D","codigo":"QT","texto":"Ela deixa outras coisas de lado e permanece com você, dando atenção exclusiva ao que você deseja conversar."},{"letra":"E","codigo":"RP","texto":"Ela escolhe e entrega, naquele momento ou pouco depois, algo simples e significativo para trazer conforto e demonstrar cuidado."}]},{"n":2,"titulo":"Uma conquista importante","situacao":"Depois de muito esforço, você alcança uma conquista pessoal, acadêmica ou profissional e compartilha a notícia com alguém importante para você.","pergunta":"Qual reação faria você se sentir mais valorizada?","alternativas":[{"letra":"A","codigo":"QT","texto":"A pessoa reserva um tempo para comemorar com você e viver aquele momento sem pressa ou distrações."},{"letra":"B","codigo":"RP","texto":"Ela pensa em algo simbólico para marcar sua conquista e entrega a você naquele dia ou assim que possível."},{"letra":"C","codigo":"PA","texto":"Ela expressa orgulho, reconhece sua dedicação e diz claramente o quanto acredita em sua capacidade."},{"letra":"D","codigo":"TF","texto":"Ela demonstra sua alegria com um abraço carinhoso ou outro gesto físico espontâneo de celebração."},{"letra":"E","codigo":"FS","texto":"Ela se oferece para ajudar em alguma providência prática relacionada à nova fase que começa."}]},{"n":3,"titulo":"Um resultado abaixo do esperado","situacao":"Você se preparou bastante para algo importante, mas o resultado não foi o que esperava. Uma amiga próxima, familiar ou pessoa com quem você se relaciona percebe sua frustração.","pergunta":"Qual atitude mais ajudaria você a se sentir amada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Ela se aproxima e oferece um abraço acolhedor, respeitando o seu momento."},{"letra":"B","codigo":"FS","texto":"Ela identifica algo concreto que pode aliviar sua situação e se dispõe a resolver isso com você."},{"letra":"C","codigo":"QT","texto":"Ela permanece ao seu lado e oferece tempo para você falar, silenciar ou simplesmente ter companhia."},{"letra":"D","codigo":"RP","texto":"Ela pensa em algo significativo que possa animá-la ou simbolizar apoio e entrega assim que possível."},{"letra":"E","codigo":"PA","texto":"Ela reconhece seu esforço e lembra que aquele resultado não diminui seu valor nem sua capacidade."}]},{"n":4,"titulo":"Seu aniversário","situacao":"Chega o dia do seu aniversário. Você não espera uma comemoração grandiosa, mas deseja perceber que é importante para as pessoas que ama.","pergunta":"O que faria esse dia ser mais significativo?","alternativas":[{"letra":"A","codigo":"RP","texto":"Receber algo escolhido com cuidado, que demonstre que a pessoa conhece seus gostos e pensou em você."},{"letra":"B","codigo":"TF","texto":"Receber um abraço afetuoso e outros gestos físicos de carinho ao longo do encontro."},{"letra":"C","codigo":"FS","texto":"Perceber que alguém cuidou de detalhes práticos para que você não precisasse se preocupar com a organização."},{"letra":"D","codigo":"PA","texto":"Ouvir palavras pessoais e sinceras sobre o que você representa na vida daquela pessoa."},{"letra":"E","codigo":"QT","texto":"Passar um período especial juntas, conversando ou fazendo algo de que você realmente gosta."}]},{"n":5,"titulo":"Um dia comum","situacao":"Não há aniversário, conquista nem problema especial. É apenas um dia normal da sua rotina.","pergunta":"Qual atitude espontânea faria você se sentir mais lembrada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Receber uma mensagem sincera dizendo algo que a pessoa admira ou valoriza em você."},{"letra":"B","codigo":"QT","texto":"Ser convidada para passar um tempo juntas, mesmo que seja para uma conversa simples ou uma atividade cotidiana."},{"letra":"C","codigo":"RP","texto":"Receber uma pequena lembrança escolhida porque combinava com você ou poderia alegrar seu dia."},{"letra":"D","codigo":"FS","texto":"Perceber que a pessoa fez algo útil para facilitar uma responsabilidade sua."},{"letra":"E","codigo":"TF","texto":"Receber um abraço, um carinho ou outro gesto físico respeitoso e afetuoso."}]},{"n":6,"titulo":"Você não está se sentindo bem","situacao":"Você acorda indisposta ou fica doente e precisa reduzir suas atividades por alguns dias.","pergunta":"Qual atitude de alguém próximo faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"A pessoa se encarrega de alguma necessidade prática, como buscar algo, organizar uma tarefa ou preparar o que você precisa."},{"letra":"B","codigo":"PA","texto":"Ela diz que você não precisa enfrentar tudo sozinha e reafirma o quanto você é importante para ela."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima com carinho, segura sua mão ou oferece um abraço, respeitando seu estado físico."},{"letra":"D","codigo":"QT","texto":"Ela permanece disponível, faz companhia e dedica tempo a você sem demonstrar pressa."},{"letra":"E","codigo":"RP","texto":"Ela leva ou envia algo escolhido para tornar sua recuperação mais confortável ou agradável."}]},{"n":7,"titulo":"Uma nova fase da vida","situacao":"Você inicia um novo trabalho, curso, projeto ou mudança importante. Está animada, mas também insegura.","pergunta":"Qual atitude de uma pessoa próxima transmitiria mais apoio?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ela reserva um momento para ouvir suas expectativas e acompanhar como você está se adaptando."},{"letra":"B","codigo":"RP","texto":"Ela escolhe algo simbólico para marcar o início da nova fase e entrega naquele momento ou pouco depois."},{"letra":"C","codigo":"PA","texto":"Ela afirma que confia em você e destaca qualidades que poderão ajudá-la nessa nova etapa."},{"letra":"D","codigo":"TF","texto":"Ela oferece um abraço ou gesto físico de incentivo antes de você começar."},{"letra":"E","codigo":"FS","texto":"Ela ajuda concretamente em alguma organização ou tarefa necessária para essa transição."}]},{"n":8,"titulo":"Depois de uma discussão com uma amiga","situacao":"Você e uma amiga próxima tiveram um conflito. As duas já conversaram, reconheceram seus erros e pediram desculpas. Agora desejam reconstruir a proximidade.","pergunta":"O que mais ajudaria você a sentir que a amizade foi restaurada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Ela se aproxima e oferece um abraço sincero, caso você se sinta confortável."},{"letra":"B","codigo":"FS","texto":"Ela faz algo concreto para reparar uma consequência prática do conflito."},{"letra":"C","codigo":"QT","texto":"Ela reserva um período para vocês ficarem juntas e retomarem a convivência com tranquilidade."},{"letra":"D","codigo":"RP","texto":"Ela entrega ou prepara algo simbólico que represente a importância da amizade."},{"letra":"E","codigo":"PA","texto":"Ela reafirma verbalmente o valor que você possui para ela e o desejo de preservar a amizade."}]},{"n":9,"titulo":"Ansiedade por uma resposta","situacao":"Você está aguardando o resultado de uma entrevista, exame, seleção ou decisão importante. A espera está deixando você ansiosa.","pergunta":"Qual atitude faria você se sentir mais amparada?","alternativas":[{"letra":"A","codigo":"RP","texto":"A pessoa leva algo simples e significativo para tornar aquele período de espera menos pesado."},{"letra":"B","codigo":"TF","texto":"Ela segura sua mão ou oferece um abraço que transmite calma e segurança."},{"letra":"C","codigo":"FS","texto":"Ela ajuda você a organizar alguma pendência prática relacionada ao resultado esperado."},{"letra":"D","codigo":"PA","texto":"Ela diz que acredita em você e lembra que seu valor não depende daquela resposta."},{"letra":"E","codigo":"QT","texto":"Ela permanece com você durante parte da espera, conversando ou fazendo companhia."}]},{"n":10,"titulo":"Uma amiga conta algo doloroso","situacao":"Uma amiga muito próxima revela que está atravessando um momento emocionalmente difícil.","pergunta":"Qual seria sua reação mais natural para demonstrar amor por ela?","alternativas":[{"letra":"A","codigo":"PA","texto":"Dizer palavras que reconheçam a dor dela e reafirmem que ela não está sozinha."},{"letra":"B","codigo":"QT","texto":"Reservar tempo para escutá-la com atenção e permanecer presente enquanto ela precisar."},{"letra":"C","codigo":"RP","texto":"Pensar em algo significativo que possa trazer conforto e entregar naquele momento ou depois."},{"letra":"D","codigo":"FS","texto":"Perguntar qual responsabilidade prática pode assumir ou aliviar para ajudá-la."},{"letra":"E","codigo":"TF","texto":"Oferecer um abraço ou gesto físico de acolhimento, caso ela se sinta confortável."}]},{"n":11,"titulo":"Um relacionamento amoroso futuro","situacao":"Imagine que você esteja construindo um relacionamento sério com um homem que respeita seus limites e deseja conhecer você profundamente.","pergunta":"Em um período comum do relacionamento, o que faria você se sentir mais amada por ele?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ele percebe uma necessidade sua e realiza algo concreto para facilitar sua rotina."},{"letra":"B","codigo":"PA","texto":"Ele expressa com sinceridade aquilo que admira em seu caráter, em suas escolhas e em quem você é."},{"letra":"C","codigo":"TF","texto":"Ele demonstra afeto por meio de abraços, mãos dadas e carinho físico respeitoso."},{"letra":"D","codigo":"QT","texto":"Ele separa momentos para estar verdadeiramente presente com você, sem distrações."},{"letra":"E","codigo":"RP","texto":"Ele escolhe pequenas lembranças significativas que demonstrem atenção aos seus gostos e à sua história."}]},{"n":12,"titulo":"Apresentação à família","situacao":"Você está namorando e chega o momento de seu namorado conhecer pessoas importantes da sua família. Você está um pouco nervosa.","pergunta":"Qual atitude dele faria você se sentir mais segura e amada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ele permanece próximo durante o encontro e procura compartilhar aquele momento com atenção."},{"letra":"B","codigo":"RP","texto":"Ele leva algo simbólico e apropriado para marcar o encontro e demonstrar consideração."},{"letra":"C","codigo":"PA","texto":"Ele diz que está feliz por conhecer pessoas importantes para você e reafirma que valoriza sua história."},{"letra":"D","codigo":"TF","texto":"Ele segura sua mão, oferece um abraço ou demonstra carinho físico de maneira respeitosa."},{"letra":"E","codigo":"FS","texto":"Ele se dispõe a ajudar em alguma tarefa ou necessidade prática relacionada ao encontro."}]},{"n":13,"titulo":"Você se sente insegura consigo mesma","situacao":"Em determinado momento, você está se sentindo insegura com sua aparência, suas escolhas ou sua capacidade.","pergunta":"Qual atitude de alguém importante teria maior impacto emocional sobre você?","alternativas":[{"letra":"A","codigo":"TF","texto":"Aproximar-se fisicamente, abraçar você e transmitir aceitação por meio do carinho."},{"letra":"B","codigo":"FS","texto":"Ajudar concretamente em algo que esteja alimentando sua insegurança ou sobrecarga."},{"letra":"C","codigo":"QT","texto":"Permanecer com você e oferecer um espaço seguro para conversar sem julgamentos."},{"letra":"D","codigo":"RP","texto":"Escolher algo simbólico que demonstre atenção e faça você se sentir especial."},{"letra":"E","codigo":"PA","texto":"Falar com sinceridade sobre qualidades reais que enxerga em você e que talvez você não esteja conseguindo perceber."}]},{"n":14,"titulo":"Uma lembrança de cuidado recebido","situacao":"Pense em uma ocasião real em que você atravessou uma dificuldade e alguém demonstrou cuidado por você.","pergunta":"Qual tipo de atitude costuma permanecer mais viva em sua memória?","alternativas":[{"letra":"A","codigo":"RP","texto":"Algo significativo que a pessoa escolheu ou preparou para tornar visível o cuidado que sentia."},{"letra":"B","codigo":"TF","texto":"Um abraço, um toque acolhedor ou a proximidade física que trouxe segurança."},{"letra":"C","codigo":"FS","texto":"Uma ajuda concreta que diminuiu seu peso naquele momento."},{"letra":"D","codigo":"PA","texto":"Palavras sinceras que deram coragem, esperança ou reafirmaram seu valor."},{"letra":"E","codigo":"QT","texto":"O tempo que a pessoa dedicou a você, permanecendo presente e atenta."}]},{"n":15,"titulo":"Um passeio planejado","situacao":"Uma amiga, familiar ou namorado deseja preparar um dia especial para você depois de um período muito corrido.","pergunta":"O que faria esse momento ter mais significado?","alternativas":[{"letra":"A","codigo":"PA","texto":"Ouvir durante o passeio palavras sinceras sobre o quanto sua presença é importante."},{"letra":"B","codigo":"QT","texto":"Ter tempo de qualidade juntas, sem pressa, interrupções ou distrações."},{"letra":"C","codigo":"RP","texto":"Receber algo simbólico relacionado ao passeio ou a uma lembrança compartilhada."},{"letra":"D","codigo":"FS","texto":"Perceber que a pessoa cuidou de toda a organização para que você pudesse apenas aproveitar."},{"letra":"E","codigo":"TF","texto":"Receber gestos físicos de carinho e proximidade durante o encontro."}]},{"n":16,"titulo":"Uma dificuldade financeira ou profissional","situacao":"Você atravessa um período de preocupação financeira ou instabilidade profissional. A pessoa próxima não consegue resolver todo o problema, mas deseja apoiá-la.","pergunta":"Qual atitude faria você sentir mais amor?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ela assume ou ajuda a organizar uma necessidade prática específica que esteja ao alcance dela."},{"letra":"B","codigo":"PA","texto":"Ela expressa confiança em sua capacidade de atravessar essa fase sem diminuir a seriedade do problema."},{"letra":"C","codigo":"TF","texto":"Ela oferece um abraço, segura sua mão ou demonstra carinho físico acolhedor."},{"letra":"D","codigo":"QT","texto":"Ela reserva tempo para ouvir, pensar com você e permanecer presente durante esse período."},{"letra":"E","codigo":"RP","texto":"Ela prepara ou entrega algo significativo que traga alívio, esperança ou a sensação de que você foi lembrada."}]},{"n":17,"titulo":"Um momento de luto ou perda","situacao":"Você enfrenta a perda de alguém, o encerramento de uma fase ou outra despedida dolorosa.","pergunta":"Qual atitude de uma pessoa próxima faria você se sentir mais acompanhada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ela permanece com você durante parte daquele período, inclusive respeitando momentos de silêncio."},{"letra":"B","codigo":"RP","texto":"Ela entrega ou prepara algo simbólico que preserve uma memória ou represente cuidado."},{"letra":"C","codigo":"PA","texto":"Ela diz palavras sinceras de presença e apoio, sem tentar apressar sua dor."},{"letra":"D","codigo":"TF","texto":"Ela oferece um abraço, segura sua mão ou permanece fisicamente próxima, respeitando seus limites."},{"letra":"E","codigo":"FS","texto":"Ela assume alguma tarefa prática para que você não precise lidar sozinha com todas as responsabilidades."}]},{"n":18,"titulo":"Depois de uma decepção amorosa","situacao":"Você passou por uma decepção em um relacionamento ou por uma experiência que abalou sua confiança no amor.","pergunta":"Qual atitude de alguém próximo mais ajudaria você a se sentir valorizada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Um abraço acolhedor ou gesto físico respeitoso que transmita segurança."},{"letra":"B","codigo":"FS","texto":"Uma ajuda concreta para reorganizar alguma parte da vida afetada por essa experiência."},{"letra":"C","codigo":"QT","texto":"Tempo e companhia para você conversar, distrair-se ou reconstruir-se sem pressa."},{"letra":"D","codigo":"RP","texto":"Algo simbólico escolhido para lembrar que você continua sendo importante e digna de cuidado."},{"letra":"E","codigo":"PA","texto":"Palavras sinceras que reafirmem seu valor sem desconsiderar a dor que você viveu."}]},{"n":19,"titulo":"Seu futuro esposo chega depois de um dia difícil","situacao":"Imagine que, no futuro, você esteja casada. Seu esposo chega em casa depois de um dia difícil, mas percebe que você também está cansada e emocionalmente sobrecarregada.","pergunta":"Qual atitude dele faria você se sentir mais amada?","alternativas":[{"letra":"A","codigo":"RP","texto":"Ele traz ou prepara algo simples e significativo para demonstrar que pensou em você."},{"letra":"B","codigo":"TF","texto":"Ele se aproxima, abraça você e oferece carinho físico com respeito e atenção."},{"letra":"C","codigo":"FS","texto":"Ele assume espontaneamente alguma tarefa para reduzir sua carga naquele momento."},{"letra":"D","codigo":"PA","texto":"Ele reconhece seu esforço e verbaliza gratidão por quem você é e pelo que tem enfrentado."},{"letra":"E","codigo":"QT","texto":"Ele reserva um período para ficar com você e ouvir como foi seu dia."}]},{"n":20,"titulo":"Pensando no relacionamento que deseja construir","situacao":"Ao imaginar um relacionamento amoroso saudável, você sabe que todas as formas de cuidado são importantes. Ainda assim, algumas manifestações provavelmente teriam maior peso emocional para você.","pergunta":"Qual situação faria você perceber com mais força que é verdadeiramente amada?","alternativas":[{"letra":"A","codigo":"PA","texto":"O homem expressa de maneira sincera e frequente o que valoriza em você e no relacionamento."},{"letra":"B","codigo":"QT","texto":"Ele protege momentos para que vocês estejam juntos, conversem e compartilhem a vida com atenção."},{"letra":"C","codigo":"RP","texto":"Ele escolhe lembranças significativas que demonstrem que conhece sua história e presta atenção em você."},{"letra":"D","codigo":"FS","texto":"Ele transforma cuidado em atitudes práticas e participa das responsabilidades que afetam sua vida."},{"letra":"E","codigo":"TF","texto":"Ele demonstra afeto por meio de abraços, proximidade e carinho físico respeitoso."}]}]},"mulher-casada":{"titulo":"Mulher · Casada","cenarios":[{"n":1,"titulo":"Uma semana muito cansativa","situacao":"Você atravessou uma semana exaustiva, acumulou responsabilidades e chegou ao fim do dia emocionalmente esgotada. Seu esposo percebe que você não está bem.","pergunta":"Qual atitude dele faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ele assume espontaneamente uma tarefa que estava pesando sobre você, permitindo que você descanse."},{"letra":"B","codigo":"PA","texto":"Ele reconhece sinceramente tudo o que você enfrentou e diz que admira sua força e seu esforço."},{"letra":"C","codigo":"TF","texto":"Ele se aproxima, abraça você demoradamente e transmite acolhimento por meio do carinho físico."},{"letra":"D","codigo":"QT","texto":"Ele deixa outras coisas de lado e permanece com você, dando atenção exclusiva ao que você deseja conversar."},{"letra":"E","codigo":"RP","texto":"Ele escolhe e entrega, naquele momento ou pouco depois, algo simples e significativo para trazer conforto."}]},{"n":2,"titulo":"Uma conquista importante","situacao":"Depois de muito esforço, você alcança uma conquista pessoal, acadêmica ou profissional e conta para o seu esposo.","pergunta":"Qual reação dele faria você se sentir mais valorizada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ele reserva um tempo para comemorar com você e viver aquele momento sem pressa ou distrações."},{"letra":"B","codigo":"RP","texto":"Ele pensa em algo simbólico para marcar sua conquista e entrega naquele dia ou assim que possível."},{"letra":"C","codigo":"PA","texto":"Ele expressa orgulho, reconhece sua dedicação e diz claramente o quanto acredita em sua capacidade."},{"letra":"D","codigo":"TF","texto":"Ele demonstra alegria com um abraço carinhoso ou outro gesto físico espontâneo de celebração."},{"letra":"E","codigo":"FS","texto":"Ele se oferece para ajudar em alguma providência prática relacionada à nova fase que começa."}]},{"n":3,"titulo":"Um resultado abaixo do esperado","situacao":"Você se preparou bastante para algo importante, mas o resultado não foi o que esperava. Seu esposo percebe sua frustração.","pergunta":"Qual atitude mais ajudaria você a se sentir amada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Ele se aproxima e oferece um abraço acolhedor, respeitando o seu momento."},{"letra":"B","codigo":"FS","texto":"Ele identifica algo concreto que pode aliviar sua situação e se dispõe a resolver isso com você."},{"letra":"C","codigo":"QT","texto":"Ele permanece ao seu lado e oferece tempo para você falar, silenciar ou simplesmente ter companhia."},{"letra":"D","codigo":"RP","texto":"Ele pensa em algo significativo que possa animá-la ou simbolizar apoio e entrega assim que possível."},{"letra":"E","codigo":"PA","texto":"Ele reconhece seu esforço e lembra que aquele resultado não diminui seu valor nem sua capacidade."}]},{"n":4,"titulo":"Seu aniversário","situacao":"Chega o dia do seu aniversário. Você não espera nada grandioso, mas deseja perceber que é importante para o seu esposo.","pergunta":"O que faria esse dia ser mais significativo?","alternativas":[{"letra":"A","codigo":"RP","texto":"Receber algo escolhido com cuidado, que demonstre que ele conhece seus gostos e pensou em você."},{"letra":"B","codigo":"TF","texto":"Receber um abraço afetuoso e outros gestos físicos de carinho ao longo do dia."},{"letra":"C","codigo":"FS","texto":"Perceber que ele cuidou de detalhes práticos para que você não precisasse se preocupar com nada."},{"letra":"D","codigo":"PA","texto":"Ouvir palavras pessoais e sinceras sobre o que você representa na vida dele."},{"letra":"E","codigo":"QT","texto":"Passar um período especial com ele, conversando ou fazendo algo de que você realmente gosta."}]},{"n":5,"titulo":"Um dia comum","situacao":"Não há data especial, conquista nem problema. É apenas um dia normal da rotina de vocês.","pergunta":"Qual atitude espontânea dele faria você se sentir mais lembrada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Receber uma mensagem sincera dizendo algo que ele admira ou valoriza em você."},{"letra":"B","codigo":"QT","texto":"Ser convidada para um tempo juntos, mesmo que seja uma conversa simples ou uma atividade cotidiana."},{"letra":"C","codigo":"RP","texto":"Receber uma pequena lembrança escolhida porque combinava com você ou poderia alegrar seu dia."},{"letra":"D","codigo":"FS","texto":"Perceber que ele fez algo útil para facilitar uma responsabilidade sua."},{"letra":"E","codigo":"TF","texto":"Receber um abraço, um carinho ou outro gesto físico afetuoso no meio do dia."}]},{"n":6,"titulo":"Você não está se sentindo bem","situacao":"Você acorda indisposta ou fica doente e precisa reduzir suas atividades por alguns dias.","pergunta":"Qual atitude do seu esposo faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ele se encarrega das necessidades práticas da casa e do que você precisaria resolver."},{"letra":"B","codigo":"PA","texto":"Ele diz que você não precisa dar conta de tudo e reafirma o quanto você é importante para ele."},{"letra":"C","codigo":"TF","texto":"Ele se aproxima com carinho, segura sua mão ou oferece um abraço, respeitando seu estado físico."},{"letra":"D","codigo":"QT","texto":"Ele permanece disponível, faz companhia e dedica tempo a você sem demonstrar pressa."},{"letra":"E","codigo":"RP","texto":"Ele leva ou providencia algo escolhido para tornar sua recuperação mais confortável."}]},{"n":7,"titulo":"Uma nova fase da vida","situacao":"Vocês iniciam uma mudança importante: um novo trabalho, uma mudança de casa, um projeto ou uma nova etapa da família. Você está animada, mas insegura.","pergunta":"Qual atitude dele transmitiria mais apoio?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ele reserva um momento para ouvir suas expectativas e acompanhar como você está se adaptando."},{"letra":"B","codigo":"RP","texto":"Ele escolhe algo simbólico para marcar o início dessa fase e entrega naquele momento ou pouco depois."},{"letra":"C","codigo":"PA","texto":"Ele afirma que confia em você e destaca qualidades que vão ajudá-la nessa etapa."},{"letra":"D","codigo":"TF","texto":"Ele oferece um abraço ou gesto físico de incentivo antes de você começar."},{"letra":"E","codigo":"FS","texto":"Ele assume concretamente parte da organização necessária para essa transição."}]},{"n":8,"titulo":"Depois de uma reconciliação","situacao":"Vocês tiveram um conflito sério. Já conversaram, reconheceram seus erros e pediram desculpas. Agora desejam reconstruir a proximidade.","pergunta":"O que mais ajudaria você a sentir que a relação foi restaurada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Ele se aproxima e oferece um abraço sincero, respeitando o seu tempo."},{"letra":"B","codigo":"FS","texto":"Ele faz algo concreto para reparar uma consequência prática do conflito."},{"letra":"C","codigo":"QT","texto":"Ele reserva um período para vocês ficarem juntos e retomarem a convivência com tranquilidade."},{"letra":"D","codigo":"RP","texto":"Ele entrega ou prepara algo simbólico que represente o valor do casamento de vocês."},{"letra":"E","codigo":"PA","texto":"Ele reafirma verbalmente o quanto você é importante e o desejo de cuidar melhor da relação."}]},{"n":9,"titulo":"Ansiedade por uma resposta","situacao":"Você está aguardando o resultado de um exame, de uma seleção ou de uma decisão importante. A espera está deixando você ansiosa.","pergunta":"Qual atitude dele faria você se sentir mais amparada?","alternativas":[{"letra":"A","codigo":"RP","texto":"Ele providencia algo simples e significativo para tornar aquele período de espera menos pesado."},{"letra":"B","codigo":"TF","texto":"Ele segura sua mão ou oferece um abraço que transmite calma e segurança."},{"letra":"C","codigo":"FS","texto":"Ele assume alguma pendência prática relacionada ao que você está esperando."},{"letra":"D","codigo":"PA","texto":"Ele diz que acredita em você e lembra que seu valor não depende daquela resposta."},{"letra":"E","codigo":"QT","texto":"Ele permanece com você durante parte da espera, conversando ou fazendo companhia."}]},{"n":10,"titulo":"Alguém próximo atravessa uma dor","situacao":"Uma pessoa muito próxima revela que está atravessando um momento emocionalmente difícil.","pergunta":"Qual dessas atitudes surgiria primeiro em você como forma de cuidado, mesmo que você pensasse antes de agir?","alternativas":[{"letra":"A","codigo":"PA","texto":"Dizer palavras que reconheçam a dor dela e reafirmem que ela não está sozinha."},{"letra":"B","codigo":"QT","texto":"Reservar tempo para escutá-la com atenção e permanecer presente enquanto ela precisar."},{"letra":"C","codigo":"RP","texto":"Pensar em algo significativo que possa trazer conforto e entregar naquele momento ou depois."},{"letra":"D","codigo":"FS","texto":"Perguntar qual responsabilidade prática você pode assumir ou aliviar para ajudá-la."},{"letra":"E","codigo":"TF","texto":"Oferecer um abraço ou gesto físico de acolhimento, caso ela se sinta confortável."}]},{"n":11,"titulo":"O cotidiano do casamento","situacao":"Em um período comum do casamento, sem crise nem comemoração, a rotina segue seu curso normal.","pergunta":"O que faria você se sentir mais amada por ele nesse período?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ele percebe uma necessidade sua e realiza algo concreto para facilitar sua rotina."},{"letra":"B","codigo":"PA","texto":"Ele expressa com sinceridade o que admira em seu caráter, em suas escolhas e em quem você é."},{"letra":"C","codigo":"TF","texto":"Ele demonstra afeto por meio de abraços, mãos dadas e carinho físico ao longo dos dias."},{"letra":"D","codigo":"QT","texto":"Ele separa momentos para estar verdadeiramente presente com você, sem distrações."},{"letra":"E","codigo":"RP","texto":"Ele escolhe pequenas lembranças que demonstrem atenção aos seus gostos e à sua história."}]},{"n":12,"titulo":"Um encontro com a família","situacao":"Vocês vão a um encontro com pessoas importantes da sua família, e você está um pouco tensa com a situação.","pergunta":"Qual atitude dele faria você se sentir mais segura e amada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ele permanece próximo durante o encontro e compartilha aquele momento com atenção."},{"letra":"B","codigo":"RP","texto":"Ele leva algo apropriado para marcar o encontro e demonstrar consideração pela sua família."},{"letra":"C","codigo":"PA","texto":"Ele fala bem de você diante das pessoas e reafirma que valoriza sua história."},{"letra":"D","codigo":"TF","texto":"Ele segura sua mão, oferece um abraço ou demonstra carinho físico discreto e respeitoso."},{"letra":"E","codigo":"FS","texto":"Ele se dispõe a ajudar em alguma tarefa ou necessidade prática relacionada ao encontro."}]},{"n":13,"titulo":"Você se sente insegura consigo mesma","situacao":"Em determinado momento, você está se sentindo insegura com sua aparência, suas escolhas ou sua capacidade.","pergunta":"Qual atitude dele teria maior impacto emocional sobre você?","alternativas":[{"letra":"A","codigo":"TF","texto":"Aproximar-se, abraçar você e transmitir aceitação por meio do carinho."},{"letra":"B","codigo":"FS","texto":"Ajudar concretamente em algo que esteja alimentando sua insegurança ou sobrecarga."},{"letra":"C","codigo":"QT","texto":"Permanecer com você e oferecer um espaço seguro para conversar sem julgamentos."},{"letra":"D","codigo":"RP","texto":"Escolher algo simbólico que demonstre atenção e faça você se sentir especial."},{"letra":"E","codigo":"PA","texto":"Falar com sinceridade sobre qualidades reais que ele enxerga em você e que você não está conseguindo perceber."}]},{"n":14,"titulo":"Uma lembrança de cuidado recebido","situacao":"Pense em uma ocasião real em que você atravessou uma dificuldade e alguém demonstrou cuidado por você.","pergunta":"Qual tipo de atitude costuma permanecer mais viva em sua memória?","alternativas":[{"letra":"A","codigo":"RP","texto":"Algo significativo que a pessoa escolheu ou preparou para tornar visível o cuidado que sentia."},{"letra":"B","codigo":"TF","texto":"Um abraço, um toque acolhedor ou a proximidade física que trouxe segurança."},{"letra":"C","codigo":"FS","texto":"Uma ajuda concreta que diminuiu seu peso naquele momento."},{"letra":"D","codigo":"PA","texto":"Palavras sinceras que deram coragem, esperança ou reafirmaram seu valor."},{"letra":"E","codigo":"QT","texto":"O tempo que a pessoa dedicou a você, permanecendo presente e atenta."}]},{"n":15,"titulo":"Um dia preparado para você","situacao":"Depois de um período muito corrido, seu esposo decide preparar um dia especial para vocês dois.","pergunta":"O que faria esse momento ter mais significado?","alternativas":[{"letra":"A","codigo":"PA","texto":"Ouvir dele, durante o dia, palavras sinceras sobre o quanto sua presença é importante."},{"letra":"B","codigo":"QT","texto":"Ter tempo de qualidade juntos, sem pressa, interrupções ou distrações."},{"letra":"C","codigo":"RP","texto":"Receber algo simbólico relacionado ao passeio ou a uma lembrança compartilhada por vocês."},{"letra":"D","codigo":"FS","texto":"Perceber que ele cuidou de toda a organização para que você pudesse apenas aproveitar."},{"letra":"E","codigo":"TF","texto":"Receber gestos físicos de carinho e proximidade durante o encontro."}]},{"n":16,"titulo":"Uma dificuldade financeira ou profissional","situacao":"A família atravessa um período de preocupação financeira ou instabilidade profissional. Ele não consegue resolver tudo, mas deseja apoiar você.","pergunta":"Qual atitude dele faria você sentir mais amor?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ele assume ou organiza uma necessidade prática específica que esteja ao alcance dele."},{"letra":"B","codigo":"PA","texto":"Ele expressa confiança na capacidade de vocês atravessarem essa fase, sem diminuir a seriedade do problema."},{"letra":"C","codigo":"TF","texto":"Ele oferece um abraço, segura sua mão ou demonstra carinho físico acolhedor."},{"letra":"D","codigo":"QT","texto":"Ele reserva tempo para ouvir, pensar junto e permanecer presente durante esse período."},{"letra":"E","codigo":"RP","texto":"Ele providencia algo significativo que traga alívio ou a sensação de que você foi lembrada."}]},{"n":17,"titulo":"Um momento de luto ou perda","situacao":"Você enfrenta a perda de alguém, o encerramento de uma fase ou outra despedida dolorosa.","pergunta":"Qual atitude dele faria você se sentir mais acompanhada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ele permanece com você durante aquele período, inclusive respeitando momentos de silêncio."},{"letra":"B","codigo":"RP","texto":"Ele prepara ou entrega algo simbólico que preserve uma memória ou represente cuidado."},{"letra":"C","codigo":"PA","texto":"Ele diz palavras sinceras de presença e apoio, sem tentar apressar sua dor."},{"letra":"D","codigo":"TF","texto":"Ele oferece um abraço, segura sua mão ou permanece fisicamente próximo, respeitando seus limites."},{"letra":"E","codigo":"FS","texto":"Ele assume as tarefas práticas para que você não precise lidar sozinha com todas as responsabilidades."}]},{"n":18,"titulo":"Depois de um período de distanciamento","situacao":"Vocês passaram por uma fase de distanciamento emocional dentro do casamento e agora estão tentando se reaproximar.","pergunta":"Qual atitude dele mais ajudaria você a se sentir valorizada de novo?","alternativas":[{"letra":"A","codigo":"TF","texto":"Voltar a ter gestos de carinho e proximidade física no dia a dia."},{"letra":"B","codigo":"FS","texto":"Ver atitudes concretas dele mudando aquilo que gerou o afastamento."},{"letra":"C","codigo":"QT","texto":"Ter de volta momentos em que vocês conversam e convivem sem pressa."},{"letra":"D","codigo":"RP","texto":"Receber algo escolhido por ele que mostre que você continua sendo importante."},{"letra":"E","codigo":"PA","texto":"Ouvir dele, com sinceridade, o que você significa e o que ele valoriza em você."}]},{"n":19,"titulo":"Ele chega depois de um dia difícil","situacao":"Seu esposo chega em casa depois de um dia difícil, mas percebe que você também está cansada e emocionalmente sobrecarregada.","pergunta":"Qual atitude dele faria você se sentir mais amada?","alternativas":[{"letra":"A","codigo":"RP","texto":"Ele traz ou prepara algo simples e significativo para demonstrar que pensou em você."},{"letra":"B","codigo":"TF","texto":"Ele se aproxima, abraça você e oferece carinho físico com respeito e atenção."},{"letra":"C","codigo":"FS","texto":"Ele assume espontaneamente alguma tarefa para reduzir sua carga naquele momento."},{"letra":"D","codigo":"PA","texto":"Ele reconhece seu esforço e verbaliza gratidão por quem você é e pelo que tem enfrentado."},{"letra":"E","codigo":"QT","texto":"Ele reserva um período para ficar com você e ouvir como foi o seu dia."}]},{"n":20,"titulo":"O casamento que você deseja preservar","situacao":"Ao pensar em um casamento saudável, você sabe que todas as formas de cuidado importam. Ainda assim, algumas têm mais peso emocional para você.","pergunta":"O que faria você perceber com mais força que é verdadeiramente amada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Ele expressa de maneira sincera e frequente o que valoriza em você e no casamento."},{"letra":"B","codigo":"QT","texto":"Ele protege momentos para que vocês estejam juntos, conversem e compartilhem a vida com atenção."},{"letra":"C","codigo":"RP","texto":"Ele escolhe lembranças significativas que demonstrem que conhece sua história e presta atenção em você."},{"letra":"D","codigo":"FS","texto":"Ele transforma cuidado em atitudes práticas e participa das responsabilidades da casa e da família."},{"letra":"E","codigo":"TF","texto":"Ele demonstra afeto por meio de abraços, proximidade e carinho físico ao longo dos dias."}]}]},"mulher-divorciada":{"titulo":"Mulher · Divorciada","cenarios":[{"n":1,"titulo":"Uma semana muito cansativa","situacao":"Você passou por uma semana exaustiva, acumulou responsabilidades e chegou ao fim do dia emocionalmente esgotada. Uma pessoa muito próxima percebe que você não está bem.","pergunta":"Qual atitude faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ela assume espontaneamente uma tarefa que estava pesando sobre você, permitindo que você descanse."},{"letra":"B","codigo":"PA","texto":"Ela reconhece sinceramente tudo o que você tem carregado e diz que admira sua força."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima, abraça você demoradamente e transmite acolhimento por meio do carinho físico."},{"letra":"D","codigo":"QT","texto":"Ela deixa outras coisas de lado e permanece com você, dando atenção exclusiva ao que você quiser conversar."},{"letra":"E","codigo":"RP","texto":"Ela providencia, naquele momento ou pouco depois, algo simples e significativo para trazer conforto."}]},{"n":2,"titulo":"Uma conquista importante","situacao":"Depois de muito esforço, você alcança uma conquista pessoal, acadêmica ou profissional e compartilha a notícia com alguém importante para você.","pergunta":"Qual reação faria você se sentir mais valorizada?","alternativas":[{"letra":"A","codigo":"QT","texto":"A pessoa reserva um tempo para comemorar com você e viver aquele momento sem pressa."},{"letra":"B","codigo":"RP","texto":"Ela pensa em algo simbólico para marcar sua conquista e entrega naquele dia ou assim que possível."},{"letra":"C","codigo":"PA","texto":"Ela expressa orgulho, reconhece sua dedicação e diz o quanto acredita na sua capacidade."},{"letra":"D","codigo":"TF","texto":"Ela demonstra alegria com um abraço ou outro gesto físico espontâneo de celebração."},{"letra":"E","codigo":"FS","texto":"Ela se oferece para ajudar em alguma providência prática relacionada à nova fase que começa."}]},{"n":3,"titulo":"Um resultado abaixo do esperado","situacao":"Você se preparou bastante para algo importante, mas o resultado não foi o que esperava. Alguém próximo percebe sua frustração.","pergunta":"Qual atitude mais ajudaria você a se sentir amada?","alternativas":[{"letra":"A","codigo":"TF","texto":"A pessoa se aproxima e oferece um abraço acolhedor, respeitando o seu momento."},{"letra":"B","codigo":"FS","texto":"Ela identifica algo concreto que pode aliviar sua situação e se dispõe a resolver isso com você."},{"letra":"C","codigo":"QT","texto":"Ela permanece ao seu lado e oferece tempo para você falar, silenciar ou apenas ter companhia."},{"letra":"D","codigo":"RP","texto":"Ela pensa em algo significativo que possa animá-la ou simbolizar apoio e entrega assim que possível."},{"letra":"E","codigo":"PA","texto":"Ela reconhece seu esforço e lembra que aquele resultado não diminui seu valor nem sua capacidade."}]},{"n":4,"titulo":"Seu aniversário","situacao":"Chega o dia do seu aniversário. Você não espera uma comemoração grandiosa, mas deseja perceber que é importante para as pessoas que ama.","pergunta":"O que faria esse dia ser mais significativo?","alternativas":[{"letra":"A","codigo":"RP","texto":"Receber algo escolhido com cuidado, que demonstre que a pessoa conhece seus gostos e pensou em você."},{"letra":"B","codigo":"TF","texto":"Receber um abraço afetuoso e outros gestos físicos de carinho ao longo do encontro."},{"letra":"C","codigo":"FS","texto":"Perceber que alguém cuidou de detalhes práticos para que você não precisasse organizar nada."},{"letra":"D","codigo":"PA","texto":"Ouvir palavras pessoais e sinceras sobre o que você representa na vida daquela pessoa."},{"letra":"E","codigo":"QT","texto":"Passar um período especial junto, conversando ou fazendo algo de que você realmente gosta."}]},{"n":5,"titulo":"Um dia comum","situacao":"Não há data especial, conquista nem problema. É apenas um dia normal da sua rotina.","pergunta":"Qual atitude espontânea faria você se sentir mais lembrada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Receber uma mensagem sincera dizendo algo que a pessoa admira ou valoriza em você."},{"letra":"B","codigo":"QT","texto":"Ser convidada para passar um tempo junto, mesmo que seja uma conversa simples ou algo cotidiano."},{"letra":"C","codigo":"RP","texto":"Receber uma pequena lembrança escolhida porque combinava com você ou poderia alegrar seu dia."},{"letra":"D","codigo":"FS","texto":"Perceber que a pessoa fez algo útil para facilitar uma responsabilidade sua."},{"letra":"E","codigo":"TF","texto":"Receber um abraço, um carinho ou outro gesto físico respeitoso e afetuoso."}]},{"n":6,"titulo":"Você não está se sentindo bem","situacao":"Você acorda indisposta ou fica doente e precisa reduzir suas atividades por alguns dias.","pergunta":"Qual atitude de alguém próximo faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"A pessoa se encarrega de alguma necessidade prática, como buscar algo, resolver uma pendência ou organizar a rotina."},{"letra":"B","codigo":"PA","texto":"Ela diz que você não precisa dar conta de tudo sozinha e reafirma o quanto você é importante para ela."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima com carinho, segura sua mão ou oferece um abraço, respeitando seu estado físico."},{"letra":"D","codigo":"QT","texto":"Ela permanece disponível, faz companhia e dedica tempo a você sem demonstrar pressa."},{"letra":"E","codigo":"RP","texto":"Ela leva ou envia algo escolhido para tornar sua recuperação mais confortável."}]},{"n":7,"titulo":"Uma nova fase da vida","situacao":"Você inicia um novo trabalho, curso, projeto ou mudança importante. Está animada, mas também insegura.","pergunta":"Qual atitude de uma pessoa próxima transmitiria mais apoio?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ela reserva um momento para ouvir suas expectativas e acompanhar como você está se adaptando."},{"letra":"B","codigo":"RP","texto":"Ela escolhe algo simbólico para marcar o início da nova fase e entrega naquele momento ou pouco depois."},{"letra":"C","codigo":"PA","texto":"Ela afirma que confia em você e destaca qualidades que poderão ajudá-la nessa etapa."},{"letra":"D","codigo":"TF","texto":"Ela oferece um abraço ou gesto físico de incentivo antes de você começar."},{"letra":"E","codigo":"FS","texto":"Ela ajuda concretamente em alguma organização ou tarefa necessária para essa transição."}]},{"n":8,"titulo":"Depois de um conflito resolvido","situacao":"Você e uma pessoa próxima tiveram um conflito. As duas já conversaram, reconheceram seus erros e pediram desculpas. Agora desejam reconstruir a proximidade.","pergunta":"O que mais ajudaria você a sentir que a relação foi restaurada?","alternativas":[{"letra":"A","codigo":"TF","texto":"Ela se aproxima e oferece um abraço sincero, caso você se sinta confortável."},{"letra":"B","codigo":"FS","texto":"Ela faz algo concreto para reparar uma consequência prática do conflito."},{"letra":"C","codigo":"QT","texto":"Ela reserva um período para vocês ficarem juntas e retomarem a convivência com tranquilidade."},{"letra":"D","codigo":"RP","texto":"Ela entrega ou prepara algo simbólico que represente a importância dessa relação."},{"letra":"E","codigo":"PA","texto":"Ela reafirma verbalmente o valor que você tem para ela e o desejo de preservar o vínculo."}]},{"n":9,"titulo":"Ansiedade por uma resposta","situacao":"Você está aguardando o resultado de uma entrevista, exame, seleção ou decisão importante. A espera está deixando você ansiosa.","pergunta":"Qual atitude faria você se sentir mais amparada?","alternativas":[{"letra":"A","codigo":"RP","texto":"A pessoa leva algo simples e significativo para tornar aquele período de espera menos pesado."},{"letra":"B","codigo":"TF","texto":"Ela segura sua mão ou oferece um abraço que transmite calma e segurança."},{"letra":"C","codigo":"FS","texto":"Ela ajuda você a organizar alguma pendência prática relacionada ao resultado esperado."},{"letra":"D","codigo":"PA","texto":"Ela diz que acredita em você e lembra que seu valor não depende daquela resposta."},{"letra":"E","codigo":"QT","texto":"Ela permanece com você durante parte da espera, conversando ou fazendo companhia."}]},{"n":10,"titulo":"Alguém próximo atravessa uma dor","situacao":"Uma pessoa muito próxima revela que está atravessando um momento emocionalmente difícil.","pergunta":"Qual dessas atitudes surgiria primeiro em você como forma de cuidado, mesmo que você pensasse antes de agir?","alternativas":[{"letra":"A","codigo":"PA","texto":"Dizer palavras que reconheçam a dor dela e reafirmem que ela não está sozinha."},{"letra":"B","codigo":"QT","texto":"Reservar tempo para escutá-la com atenção e permanecer presente enquanto ela precisar."},{"letra":"C","codigo":"RP","texto":"Pensar em algo significativo que possa trazer conforto e entregar naquele momento ou depois."},{"letra":"D","codigo":"FS","texto":"Perguntar qual responsabilidade prática você pode assumir ou aliviar para ajudá-la."},{"letra":"E","codigo":"TF","texto":"Oferecer um abraço ou gesto físico de acolhimento, caso ela se sinta confortável."}]},{"n":11,"titulo":"As relações da sua vida hoje","situacao":"Pense nas relações significativas que fazem parte da sua vida atualmente: família, amizades, pessoas com quem você convive no dia a dia.","pergunta":"O que faria você se sentir mais amada dentro dessas relações?","alternativas":[{"letra":"A","codigo":"FS","texto":"Perceberem uma necessidade sua e realizarem algo concreto para facilitar sua rotina."},{"letra":"B","codigo":"PA","texto":"Expressarem com sinceridade o que admiram no seu caráter, nas suas escolhas e em quem você é."},{"letra":"C","codigo":"TF","texto":"Demonstrarem afeto por meio de abraços e contato físico respeitoso e acolhedor."},{"letra":"D","codigo":"QT","texto":"Separarem momentos para estar verdadeiramente presentes com você, sem distrações."},{"letra":"E","codigo":"RP","texto":"Escolherem pequenas lembranças que demonstrem atenção aos seus gostos e à sua história."}]},{"n":12,"titulo":"Um encontro com a família","situacao":"Você participa de um encontro com pessoas importantes da sua família. Por algum motivo, esse encontro exige um pouco mais de você.","pergunta":"Qual atitude de alguém próximo faria você se sentir mais segura e amada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ela permanece próxima durante o encontro e compartilha aquele momento com atenção."},{"letra":"B","codigo":"RP","texto":"Ela leva algo apropriado para marcar o encontro e demonstrar consideração."},{"letra":"C","codigo":"PA","texto":"Ela fala bem de você diante das pessoas e reafirma que valoriza sua história."},{"letra":"D","codigo":"TF","texto":"Ela oferece um abraço ou demonstra carinho físico discreto quando percebe sua tensão."},{"letra":"E","codigo":"FS","texto":"Ela se dispõe a ajudar em alguma tarefa ou necessidade prática relacionada ao encontro."}]},{"n":13,"titulo":"Você se sente insegura consigo mesma","situacao":"Em determinado momento, você está se sentindo insegura com sua aparência, suas escolhas ou sua capacidade.","pergunta":"Qual atitude de alguém importante teria maior impacto emocional sobre você?","alternativas":[{"letra":"A","codigo":"TF","texto":"Aproximar-se, abraçar você e transmitir aceitação por meio do carinho."},{"letra":"B","codigo":"FS","texto":"Ajudar concretamente em algo que esteja alimentando sua insegurança ou sobrecarga."},{"letra":"C","codigo":"QT","texto":"Permanecer com você e oferecer um espaço seguro para conversar sem julgamentos."},{"letra":"D","codigo":"RP","texto":"Escolher algo simbólico que demonstre atenção e faça você se sentir especial."},{"letra":"E","codigo":"PA","texto":"Falar com sinceridade sobre qualidades reais que enxerga em você e que talvez você não esteja percebendo."}]},{"n":14,"titulo":"Uma lembrança de cuidado recebido","situacao":"Pense em uma ocasião real em que você atravessou uma dificuldade e alguém demonstrou cuidado por você.","pergunta":"Qual tipo de atitude costuma permanecer mais viva em sua memória?","alternativas":[{"letra":"A","codigo":"RP","texto":"Algo significativo que a pessoa escolheu ou preparou para tornar visível o cuidado que sentia."},{"letra":"B","codigo":"TF","texto":"Um abraço, um toque acolhedor ou a proximidade física que trouxe segurança."},{"letra":"C","codigo":"FS","texto":"Uma ajuda concreta que diminuiu seu peso naquele momento."},{"letra":"D","codigo":"PA","texto":"Palavras sinceras que deram coragem, esperança ou reafirmaram seu valor."},{"letra":"E","codigo":"QT","texto":"O tempo que a pessoa dedicou a você, permanecendo presente e atenta."}]},{"n":15,"titulo":"Um dia preparado para você","situacao":"Depois de um período muito corrido, alguém próximo decide preparar um dia especial para você.","pergunta":"O que faria esse momento ter mais significado?","alternativas":[{"letra":"A","codigo":"PA","texto":"Ouvir durante o encontro palavras sinceras sobre o quanto sua presença é importante."},{"letra":"B","codigo":"QT","texto":"Ter tempo de qualidade juntas, sem pressa, interrupções ou distrações."},{"letra":"C","codigo":"RP","texto":"Receber algo simbólico relacionado ao passeio ou a uma lembrança compartilhada."},{"letra":"D","codigo":"FS","texto":"Perceber que a pessoa cuidou de toda a organização para que você pudesse apenas aproveitar."},{"letra":"E","codigo":"TF","texto":"Receber gestos físicos de carinho e proximidade durante o encontro."}]},{"n":16,"titulo":"Uma dificuldade financeira ou profissional","situacao":"Você atravessa um período de preocupação financeira ou instabilidade profissional. A pessoa próxima não consegue resolver o problema, mas deseja apoiá-la.","pergunta":"Qual atitude faria você sentir mais amor?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ela assume ou ajuda a organizar uma necessidade prática específica que esteja ao alcance dela."},{"letra":"B","codigo":"PA","texto":"Ela expressa confiança na sua capacidade de atravessar essa fase, sem diminuir a seriedade do problema."},{"letra":"C","codigo":"TF","texto":"Ela oferece um abraço, segura sua mão ou demonstra carinho físico acolhedor."},{"letra":"D","codigo":"QT","texto":"Ela reserva tempo para ouvir, pensar com você e permanecer presente durante esse período."},{"letra":"E","codigo":"RP","texto":"Ela prepara ou entrega algo significativo que traga alívio ou a sensação de que você foi lembrada."}]},{"n":17,"titulo":"Um momento de luto ou perda","situacao":"Você enfrenta a perda de alguém querido, o encerramento de uma fase ou outra despedida dolorosa.","pergunta":"Qual atitude de uma pessoa próxima faria você se sentir mais acompanhada?","alternativas":[{"letra":"A","codigo":"QT","texto":"Ela permanece com você durante parte daquele período, inclusive respeitando o silêncio."},{"letra":"B","codigo":"RP","texto":"Ela entrega ou prepara algo simbólico que preserve uma memória ou represente cuidado."},{"letra":"C","codigo":"PA","texto":"Ela diz palavras sinceras de presença e apoio, sem tentar apressar sua dor."},{"letra":"D","codigo":"TF","texto":"Ela oferece um abraço ou permanece fisicamente próxima, respeitando seus limites."},{"letra":"E","codigo":"FS","texto":"Ela assume alguma tarefa prática para que você não precise lidar sozinha com tudo."}]},{"n":18,"titulo":"Reconstruindo a vida","situacao":"Você atravessa um período de reconstrução, reorganizando rotina, planos e o modo como sua vida está estruturada agora.","pergunta":"Qual atitude de alguém próximo mais ajudaria você a se sentir valorizada nessa fase?","alternativas":[{"letra":"A","codigo":"TF","texto":"Um abraço acolhedor ou gesto físico respeitoso que transmita segurança."},{"letra":"B","codigo":"FS","texto":"Uma ajuda concreta para reorganizar alguma parte prática da vida que mudou."},{"letra":"C","codigo":"QT","texto":"Tempo e companhia para você conversar, respirar ou se reconstruir sem pressa."},{"letra":"D","codigo":"RP","texto":"Algo simbólico escolhido para lembrar que você continua sendo importante e digna de cuidado."},{"letra":"E","codigo":"PA","texto":"Palavras sinceras que reafirmem seu valor sem desconsiderar o que você viveu."}]},{"n":19,"titulo":"O fim de um dia difícil","situacao":"Você chega ao fim de um dia difícil e alguém com quem você convive percebe que você está cansada e sobrecarregada.","pergunta":"Qual atitude faria você se sentir mais amada?","alternativas":[{"letra":"A","codigo":"RP","texto":"Essa pessoa traz ou prepara algo simples e significativo para demonstrar que pensou em você."},{"letra":"B","codigo":"TF","texto":"Ela se aproxima, abraça você e oferece carinho físico com respeito e atenção."},{"letra":"C","codigo":"FS","texto":"Ela assume espontaneamente alguma tarefa para reduzir sua carga naquele momento."},{"letra":"D","codigo":"PA","texto":"Ela reconhece seu esforço e verbaliza gratidão por quem você é e pelo que tem enfrentado."},{"letra":"E","codigo":"QT","texto":"Ela reserva um período para ficar com você e ouvir como foi o seu dia."}]},{"n":20,"titulo":"As relações que você deseja viver","situacao":"Ao pensar nas relações que deseja cultivar daqui em diante, sejam elas familiares, de amizade ou afetivas, você sabe que todas as formas de cuidado importam. Ainda assim, algumas têm mais peso emocional para você.","pergunta":"O que faria você perceber com mais força que é verdadeiramente amada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Ouvir com sinceridade e frequência o que as pessoas valorizam em você."},{"letra":"B","codigo":"QT","texto":"Que protejam momentos para estarem com você, conversarem e compartilharem a vida com atenção."},{"letra":"C","codigo":"RP","texto":"Que escolham lembranças significativas mostrando que conhecem sua história e prestam atenção em você."},{"letra":"D","codigo":"FS","texto":"Que transformem cuidado em atitudes práticas e participem das responsabilidades que afetam sua vida."},{"letra":"E","codigo":"TF","texto":"Que demonstrem afeto por meio de abraços, proximidade e carinho físico respeitoso."}]}]},"mulher-viuva":{"titulo":"Mulher · Viúva","cenarios":[{"n":1,"titulo":"Uma semana muito cansativa","situacao":"Você passou por uma semana exaustiva, acumulou responsabilidades e chegou ao fim do dia emocionalmente esgotada. Uma pessoa muito próxima percebe que você não está bem.","pergunta":"Qual atitude faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"Ela assume espontaneamente uma tarefa que estava pesando sobre você, permitindo que você descanse."},{"letra":"B","codigo":"PA","texto":"Ela reconhece sinceramente tudo o que você tem carregado e diz que admira sua força."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima, abraça você demoradamente e transmite acolhimento por meio do carinho físico."},{"letra":"D","codigo":"QT","texto":"Ela deixa outras coisas de lado e permanece com você, dando atenção exclusiva ao que você quiser conversar."},{"letra":"E","codigo":"RP","texto":"Ela providencia, naquele momento ou pouco depois, algo simples e significativo para trazer conforto."}]},{"n":2,"titulo":"Uma conquista importante","situacao":"Depois de muito esforço, você alcança uma conquista pessoal, acadêmica ou profissional e compartilha a notícia com alguém importante para você.","pergunta":"Qual reação faria você se sentir mais valorizada?","alternativas":[{"letra":"A","codigo":"QT","texto":"A pessoa reserva um tempo para comemorar com você e viver aquele momento sem pressa."},{"letra":"B","codigo":"RP","texto":"Ela pensa em algo simbólico para marcar sua conquista e entrega naquele dia ou assim que possível."},{"letra":"C","codigo":"PA","texto":"Ela expressa orgulho, reconhece sua dedicação e diz o quanto acredita na sua capacidade."},{"letra":"D","codigo":"TF","texto":"Ela demonstra alegria com um abraço ou outro gesto físico espontâneo de celebração."},{"letra":"E","codigo":"FS","texto":"Ela se oferece para ajudar em alguma providência prática relacionada à nova fase que começa."}]},{"n":3,"titulo":"Um resultado abaixo do esperado","situacao":"Você se preparou bastante para algo importante, mas o resultado não foi o que esperava. Alguém próximo percebe sua frustração.","pergunta":"Qual atitude mais ajudaria você a se sentir amada?","alternativas":[{"letra":"A","codigo":"TF","texto":"A pessoa se aproxima e oferece um abraço acolhedor, respeitando o seu momento."},{"letra":"B","codigo":"FS","texto":"Ela identifica algo concreto que pode aliviar sua situação e se dispõe a resolver isso com você."},{"letra":"C","codigo":"QT","texto":"Ela permanece ao seu lado e oferece tempo para você falar, silenciar ou apenas ter companhia."},{"letra":"D","codigo":"RP","texto":"Ela pensa em algo significativo que possa animá-la ou simbolizar apoio e entrega assim que possível."},{"letra":"E","codigo":"PA","texto":"Ela reconhece seu esforço e lembra que aquele resultado não diminui seu valor nem sua capacidade."}]},{"n":4,"titulo":"Seu aniversário","situacao":"Chega o dia do seu aniversário. Você não espera uma comemoração grandiosa, mas deseja perceber que é importante para as pessoas que ama.","pergunta":"O que faria esse dia ser mais significativo?","alternativas":[{"letra":"A","codigo":"RP","texto":"Receber algo escolhido com cuidado, que demonstre que a pessoa conhece seus gostos e pensou em você."},{"letra":"B","codigo":"TF","texto":"Receber um abraço afetuoso e outros gestos físicos de carinho ao longo do encontro."},{"letra":"C","codigo":"FS","texto":"Perceber que alguém cuidou de detalhes práticos para que você não precisasse organizar nada."},{"letra":"D","codigo":"PA","texto":"Ouvir palavras pessoais e sinceras sobre o que você representa na vida daquela pessoa."},{"letra":"E","codigo":"QT","texto":"Passar um período especial junto, conversando ou fazendo algo de que você realmente gosta."}]},{"n":5,"titulo":"Um dia comum","situacao":"Não há data especial, conquista nem problema. É apenas um dia normal da sua rotina.","pergunta":"Qual atitude espontânea faria você se sentir mais lembrada?","alternativas":[{"letra":"A","codigo":"PA","texto":"Receber uma mensagem sincera dizendo algo que a pessoa admira ou valoriza em você."},{"letra":"B","codigo":"QT","texto":"Ser convidada para passar um tempo junto, mesmo que seja uma conversa simples ou algo cotidiano."},{"letra":"C","codigo":"RP","texto":"Receber uma pequena lembrança escolhida porque combinava com você ou poderia alegrar seu dia."},{"letra":"D","codigo":"FS","texto":"Perceber que a pessoa fez algo útil para facilitar uma responsabilidade sua."},{"letra":"E","codigo":"TF","texto":"Receber um abraço, um carinho ou outro gesto físico respeitoso e afetuoso."}]},{"n":6,"titulo":"Você não está se sentindo bem","situacao":"Você acorda indisposta ou fica doente e precisa reduzir suas atividades por alguns dias.","pergunta":"Qual atitude de alguém próximo faria você se sentir mais cuidada?","alternativas":[{"letra":"A","codigo":"FS","texto":"A pessoa se encarrega de alguma necessidade prática, como buscar algo, resolver uma pendência ou organizar a rotina."},{"letra":"B","codigo":"PA","texto":"Ela diz que você não precisa dar conta de tudo sozinha e reafirma o quanto você é importante para ela."},{"letra":"C","codigo":"TF","texto":"Ela se aproxima com carinho, segura sua mão ou oferece um abraço, respeitando seu estado físico."},{"letra":"D","codigo":"QT","texto":"Ela permanece disponível, faz companhia e dedica tempo a você sem demonstrar pressa."},{"letra":"E","codigo":"RP","texto":"Ela leva o